from pathlib import Path
import sys
import os
import shutil

DOWNLOADS_ROOT = Path(sys.argv[1])

for dirpath, dirnames, filenames in os.walk(DOWNLOADS_ROOT):
    for subdir_name in dirnames:
        subdir_path = DOWNLOADS_ROOT / subdir_name

        shutil.make_archive(subdir_name, 'zip', subdir_path)

        shutil.rmtree(subdir_path)

    break

# by default the upload-pages-artifact action used by the docs workflow will create a file named 'artifact.tar'
docs_path = DOWNLOADS_ROOT / 'artifact'

shutil.make_archive('BenBot-docs', 'zip', docs_path)

shutil.rmtree(docs_path)
